function drawJungle(t){const beat=reducedMotion?0:t;ctx.save();ctx.globalAlpha=isRana()?.12:.045;for(let i=0;i<7;i++){const x=i*350-camera*.12+Math.sin(beat*.3+i)*45,y=430+Math.cos(beat*.3+i)*170;ctx.strokeStyle=['#ff88ea','#9bffee','#ffd064'][i%3];ctx.lineWidth=9;ctx.beginPath();for(let a=0;a<Math.PI*5;a+=.09){const r=a*11;const px=x+Math.cos(a+beat*.1)*r,py=y+Math.sin(a+beat*.1)*r;a?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.stroke();}ctx.restore();if(!dancers.complete||!dancers.naturalWidth)return;const slices=[[0,535],[535,460],[995,541]];for(let i=0;i<15;i++){const type=i%3,worldX=360+i*242,x=worldX-camera,y=i%2===0?830:340;if(x<-150||x>vw+150)continue;const bounce=reducedMotion?0:Math.abs(Math.sin(t*3.1+i))*15,sway=reducedMotion?0:Math.sin(t*2.5+i)*.14;const heights=[115,120,158],h=heights[type],w=h*slices[type][1]/dancers.naturalHeight;ctx.save();ctx.translate(x,y-bounce);ctx.rotate(sway);ctx.drawImage(dancers,slices[type][0],0,slices[type][1],dancers.naturalHeight,-w/2,-h,w,h);ctx.restore();if(!reducedMotion&&isRana()&&i%2===0){ctx.fillStyle=['#ffc5ee','#a6ffe1','#ffeba7'][type];ctx.font='24px sans-serif';ctx.fillText('♪',x+32,y-h+Math.sin(t*2+i)*12);}}}
function updatePortal(dt){portalTime+=dt;if(portalTime>=3.4&&!portalSwitched){stage=portalFrom+1;loadStage();portalSwitched=true;$('portal-title').textContent=currentStage().name;$('portal-sub').textContent=currentStage().portalSub;tone(523,.3);tone(784,.3);}if(portalTime>=7){state='playing';$('portal-caption').style.display='none';elapsed=0;keys.clear();canvas.focus();hud();if(mode==='sarah')openDialogue(currentStage().intro);}}
function drawPortal(t){const p=portalTime;ctx.save();const fade=p<3.4?clamp(p/2.6,0,.9):clamp((7-p)/3.5,0,.7);ctx.fillStyle='rgba(20,7,53,'+fade+')';ctx.fillRect(0,0,vw,H);const r=p<3.4?60+p*48:225-(p-3.4)*22;drawOrnatePortal(vw/2,H*.53,r*2,t,true);ctx.restore();let size=p<3.4?Math.max(.1,1-p/3.5):Math.min(1,(p-3.4)/1.4);const x=p<3.4?(nessie.x-camera)+(vw/2-(nessie.x-camera))*clamp(p/2,0,1):vw/2+(nessie.x-camera-vw/2)*clamp((p-4)/2,0,1);const arrive=smoothUnit((p-3.4)/3.6),entryY=H*.53+(nessie.y+(reducedMotion?0:Math.sin(t*3)*3)-H*.53)*arrive;drawNessie(x,entryY,size,t,reducedMotion?0:p<3.4?p*2.5:8.5*(1-arrive));ctx.save();const a=p>3.05&&p<3.75?Math.sin((p-3.05)/.7*Math.PI)*.65:0;ctx.fillStyle='rgba(228,198,255,'+Math.max(0,a)+')';ctx.fillRect(0,0,vw,H);ctx.restore();}
