function drawFloraLayer(t,speed,height,alpha,offset=0){if(!floraArt.complete||!floraArt.naturalWidth)return;const width=height*floraArt.naturalWidth/floraArt.naturalHeight;const shift=camera*speed;const first=Math.floor(shift/width)-1;ctx.save();ctx.globalAlpha=alpha;for(let i=first;i<first+Math.ceil(vw/width)+3;i++){const wave=reducedMotion?0:Math.sin(t*.7+i*1.9)*7;const x=i*width-shift;ctx.save();ctx.translate(x+width/2+wave,H-height+offset);if(i%2)ctx.scale(-1,1);ctx.transform(1,0,reducedMotion?0:Math.sin(t*.5+i)*.016,1,0,0);ctx.drawImage(floraArt,-width/2,0,width,height);ctx.restore();}ctx.restore();}
