function drawBarrier(o,x,t,index){if(isTraining()||isPalace()){drawFamilyBarrier(o,x,t);return;}const art=stage===0?reefArt:rootArt;ctx.save();ctx.translate(x,o.y);ctx.shadowColor=stage===0?'#0b455388':'#27295188';ctx.shadowBlur=18;ctx.shadowOffsetY=8;if(art.complete&&art.naturalWidth){const padX=o.w*.5,padY=14;if(o.y===280){ctx.translate(0,o.h);ctx.scale(1,-1);}ctx.drawImage(art,0,0,art.naturalWidth,art.naturalHeight,-padX,-padY,o.w+padX*2,o.h+padY*2);}else{const g=ctx.createLinearGradient(0,0,o.w,o.h);g.addColorStop(0,'#538b88');g.addColorStop(1,'#173d50');ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(0,0,o.w,o.h,20);ctx.fill();}ctx.restore();if(floraArt.complete&&floraArt.naturalWidth){ctx.save();ctx.globalAlpha=.9;const h=105,w=h*floraArt.naturalWidth/floraArt.naturalHeight;const hanging=o.y===280;ctx.translate(x+o.w*.5,o.y+(hanging?o.h-32:28));if(hanging)ctx.scale(1,-1);const sway=reducedMotion?0:Math.sin(t*.85+index)*.025;ctx.transform(1,0,sway,1,0,0);ctx.drawImage(floraArt,-w/2,-h,w,h);ctx.restore();}ctx.save();for(let j=0;j<4;j++){const phase=t*.65+index*2+j;const px=x+14+(j*.29+.08)*o.w+(reducedMotion?0:Math.sin(phase)*3),py=o.y+o.h*.26+j*o.h*.16;const glow=ctx.createRadialGradient(px,py,0,px,py,13);glow.addColorStop(0,stage===0?'#adffe82e':'#efbbff32');glow.addColorStop(1,'#afffe000');ctx.fillStyle=glow;ctx.fillRect(px-13,py-13,26,26);}ctx.restore();}
function selectStage(next){selectedStartStage=clamp(Number(next),mode==='trial'?0:-1,STAGES.length-1);try{localStorage.setItem('sarah-family-stage-v17',String(selectedStartStage));}catch{}for(const i of [-1,0,1,2,3]){const btn=$(i===-1?'stage-training':'stage-'+i);btn.classList.toggle('selected',i===selectedStartStage);btn.setAttribute('aria-pressed',String(i===selectedStartStage));}const meta=selectedStartStage===-1?TRAINING_STAGE:STAGES[selectedStartStage];$('selected-stage').textContent=meta.storyName;$('play').textContent='Play selected stage';$('skip-training').style.display=mode!=='trial'&&selectedStartStage===-1?'inline-flex':'none';$('training-hero-choice').style.display=mode!=='trial'&&selectedStartStage===-1?'flex':'none';}
