if(isRana()){drawRanaArena(t);drawRanaHazards(t);drawRanaAttacks(t);}if(bossDefeat>0&&stage>=0&&stage<2)drawBossDefeat(t);if(isPalace())drawPalaceWorld(t);if(isTraining())drawTrainingWorld(t);
