function renderSpeechAvatar(key,name,target){if(key.startsWith('daddy')||key.startsWith('queen')||key==='royal-guard'){renderFamilyPortrait(key,name,target);return;}target.innerHTML='';target.dataset.character=key;if(key==='trio'){target.classList.add('portrait-trio');for(const [i,friend]of ['frog','lola','fifi'].entries()){const slot=document.createElement('div');slot.className='trio-face trio-'+i;target.appendChild(slot);renderSpeechAvatar(friend,['Frog DJ','Lola the Lizard','Fifi the Flamingo'][i],slot);}return;}target.classList.remove('portrait-trio');const spec=speechPortraits[key]||speechPortraits.sarah;target.style.setProperty('--portrait-glow',spec.color);const tile=document.createElement('canvas');tile.width=tile.height=320;tile.setAttribute('role','img');tile.setAttribute('aria-label',name);target.appendChild(tile);const paint=()=>{if(target.dataset.character!==key)return;const pc=tile.getContext('2d'),a=spec.art;pc.clearRect(0,0,320,320);pc.imageSmoothingEnabled=true;pc.imageSmoothingQuality='high';const [x,y,w,h]=spec.crop;pc.drawImage(a,x*a.naturalWidth,y*a.naturalHeight,w*a.naturalWidth,h*a.naturalHeight,0,0,320,320);};if(spec.art.complete&&spec.art.naturalWidth)paint();else spec.art.addEventListener('load',paint,{once:true});}
const conversations={
intro:{speaker:'Nessie',portrait:'nessie.png',line:'Sarah Maria! Carlo has pinched the gold. I would help, but I have a very important appointment with… floating.',options:[['I’ll handle it. You practise floating.','Excellent. I’m already internationally qualified.'],['Does the treasure include snacks?','I heard Carlo has a secret stash of seaweed crisps. That crab is living large.']],hint:'Swim with WASD or arrows. Boost with Space. At a glowing launch ring, Boost to leap for sky power-ups. Steer in the air; Down dives. Hit bosses when they glow.'},
scout:{speaker:'Sardine Scout',portrait:'scout',line:'Psst! Carlo is hiding up ahead. His hat is enormous, but his patience is tiny.',options:[['How do I beat him?','Dodge his shells. When he glows green, boost straight into him. He calls it “taking a fancy nap”.'],['Can I borrow a tiny fish helmet?','We only stock size Sardine. Your hair would require planning permission.']],hint:'Checkpoint reached. You can return here if you run out of hearts.'},
carlo:{speaker:'Carlo the Crab',portrait:'carlo.png',line:'HALT! I am Carlo, owner of this treasure, this monocle, and three extremely sophisticated hats.',options:[['Does your hat have a swimming licence?','It has a degree in Fancy. And a minor in Being Fabulous.'],['Nice monocle. Can it see you losing?','Absurd! …Although the warranty does mention embarrassing defeats.']],hint:'Carlo throws shells, then drops his guard. Watch for BOOST NOW.'},
'carlo-win':{speaker:'Carlo the Crab',portrait:'carlo.png',line:'My gold! My dignity! At least my hat is still waterproof. I demand a rematch after afternoon tea.',options:[['Try sharing the gold next time.','Sharing? Hmm. Is that the thing where I don’t keep all of it? Intriguing.'],['Your hat fought very bravely.','Thank you. It shall receive a medal and its own tiny hat.']],hint:'The portal is open. Swim into it to reach Colombia.'},
frog:{speaker:'Frog DJ',portrait:'frog',line:'Welcome to Colombia, Sarah Maria! We were dancing until Miguel declared this a NO-FUN lagoon. The audacity. The terrible rhythm.',options:[['Let’s bring the groove back!','That’s the spirit! I’ve got the beats. You’ve got the tail.'],['What kind of music do frogs like?','Hip-hop. Obviously. We take the hopping very seriously.']],hint:'The currents are stronger here. Miguel fires starfish and swoops before glowing.'},
lizard:{speaker:'Lola the Lizard',portrait:'lola',line:'Miguel says he’s the coolest creature in the lagoon. I wear imaginary sunglasses, so that’s obviously incorrect.',options:[['Any boss-fighting tips?','Dodge his starfish fan and his swoop. When he glows, boost! Even cool rays need a breather.'],['Can I try the imaginary sunglasses?','Certainly. Wow. Instant superstar. Please return them to the imaginary case.']],hint:'Checkpoint reached. Save your boost for Miguel’s vulnerable moment.'},
miguel:{speaker:'Miguel the Manta Ray',portrait:'miguel.png',line:'I am Miguel! Master of the lagoon! King of the swoop! Absolutely not a floating pancake!',options:[['A very dramatic floating pancake.','A DESIGNER pancake. With premium aerodynamic edges.'],['Your starfish want a holiday.','They get Tuesdays off. …Wait, is it Tuesday?']],hint:'Avoid the starfish and swoop. Boost into Miguel when his halo turns green.'},
'miguel-win':{speaker:'Miguel the Manta Ray',portrait:'miguel.png',line:'Defeated by a mermaid! I’m retiring from villainy. Perhaps I’ll open a pancake café. Do not laugh.',options:[['I’ll have the seaweed special.','Excellent taste. Five stars. No, those are actual starfish.'],['You could join the dancing instead.','Fine. But my signature move is still called The Extremely Menacing Swoop.']],hint:'Enter the open portal. The rainbow jungle is waiting.'},
flamingo:{speaker:'Fifi the Flamingo',portrait:'fifi',line:'Sarah Maria, darling! You saved the party! I’ve been standing on one leg for HOURS waiting for this moment.',options:[['Why not use the other leg?','And ruin the dramatic entrance? Absolutely not.'],['Show me your best dance move.','Behold: The Pink Wobble. Elegant. Unstable. Award-winning.']],hint:'Explore the rainbow jungle and enter the final portal to finish your adventure.'},
'final-boss':{speaker:'Rana Rex',portrait:'rana-rex.png',line:'SILENCE, TINY SWIMMER! I am Rana Rex, the scaled sovereign of this rainbow jungle. My eyes burn, my vines listen, and this party is cancelled.',options:[['Your laser eyes need a dance lesson.','INSOLENCE! I shall turn the whole lagoon into a laser disco of doom!'],['What happened to your sense of fun?','I traded it for a second set of eyelids. Much more practical.']],hint:'Rana Rex uses sweeping laser eyes, acid volleys, orbiting seeds, shockwaves, and living jungle hazards. Boost only when the halo turns green.'},
'final-boss-win':{speaker:'Rana Rex',portrait:'rana-rex.png',line:'My lasers! My vines! My perfectly intimidating reptile frog dignity! Fine, the party may resume… but I am keeping one disco ball.',options:[['You can keep the disco ball.','A generous victor. I shall guard it menacingly at all future celebrations.'],['Try dancing instead of ruling.','I know one move: The Terrifying Toadstool. It is… surprisingly catchy.']],hint:'The final portal is open. Enter it to finish the adventure.'},
final:{speaker:'The Dancing Trio',portrait:'trio',line:'The gold is safe, the lagoon is free, and nobody is throwing starfish at our dance floor. Three cheers for Sarah Maria!',options:[['Best underwater party ever!','Frog DJ: Drop the beat! Lola: Mind the tail! Fifi: Someone hold my imaginary handbag!'],['Next time I’m bringing snacks.','Nessie: Did someone say snacks? My floating appointment has mysteriously been cancelled.']],hint:'Adventure complete. Sarah Maria is a lagoon legend.'}
};
