function selectDialogue(index){const options=$('dialogue-options')?.querySelectorAll('button')||[];if(!options.length)return;dialogueChoiceIndex=clamp(index,0,options.length-1);options[dialogueChoiceIndex].click();}
function openDialogue(id,after=null){return startConversation(id,after);}
function finishDialogue(){dialogueFlow=null;document.querySelector('.game-shell')?.classList.remove('conversation-active');$('dialogue-panel').style.display='none';keys.clear();state='playing';dashTime=0;nessie.vx*=.25;nessie.vy*=.25;invincible=Math.max(invincible,.65);const after=dialogueAfter;dialogueAfter=null;if(after)after();else canvas.focus();}
const menuMarkup=$('overlay').innerHTML;
let frameDelta=1/60;function frame(now){const dt=Math.min((now-last)/1000||0,.1);frameDelta=dt;last=now;if(state==='ready')titleSceneTime+=Math.min(dt,.05);advanceSimulation(dt);if(now-lastHudPaint>=50){hud();lastHudPaint=now;}updateMusic(dt);draw(now/1000);syncTutorialUi();syncHighlandUi();if(now>toastUntil)$('toast').style.opacity='0';requestAnimationFrame(frame);}requestAnimationFrame(frame);
$('play').onclick=start;$('modes').onclick=showMenu;$('mode-story').onclick=()=>chooseMode('story');$('mode-trial').onclick=()=>chooseMode('trial');$('mode-sarah').onclick=()=>chooseMode('sarah');bindMenu();$('pause').onclick=pause;$('sound').onclick=toggleGameSound;initGameSound();$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.game-shell').requestFullscreen();}catch{flash('Fullscreen is unavailable in this browser');}};
window.addEventListener('keydown',e=>{if(handleConversationKey(e))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','p'].includes(e.key.toLowerCase())||e.key.startsWith('Arrow')){if(e.target.tagName!=='BUTTON')e.preventDefault();}const key=e.key.length===1?e.key.toLowerCase():e.key;if(key==='p'&&!e.repeat){pause();return;}keys.add(key);if(key===' '&&!e.repeat)burst();});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));
function clearHeldControls(){keys.clear();for(const [pointerId,b] of activeTouchPointers){try{if(b.hasPointerCapture?.(pointerId))b.releasePointerCapture?.(pointerId);}catch{}b.classList?.remove('is-pressed');b.setAttribute?.('aria-pressed','false');}activeTouchPointers.clear();}
window.addEventListener('blur',()=>{clearHeldControls();if(state==='playing'||state==='portal')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearHeldControls();if(state==='playing'||state==='portal')pause();}});
for(const b of document.querySelectorAll('[data-key]')){b.setAttribute('aria-pressed','false');b.addEventListener('pointerdown',e=>{e.preventDefault();try{b.setPointerCapture?.(e.pointerId);}catch{}activeTouchPointers.set(e.pointerId,b);keys.add(b.dataset.key);b.classList?.add('is-pressed');b.setAttribute('aria-pressed','true');if(b.dataset.key===' ')burst();});const release=e=>{const pointerId=e?.pointerId;if(pointerId!=null)activeTouchPointers.delete(pointerId);else for(const [id,owner] of [...activeTouchPointers])if(owner===b)activeTouchPointers.delete(id);const stillHeld=[...activeTouchPointers.values()].some(owner=>owner.dataset.key===b.dataset.key);if(!stillHeld)keys.delete(b.dataset.key);const buttonHeld=[...activeTouchPointers.values()].some(owner=>owner===b);if(!buttonHeld){b.classList?.remove('is-pressed');b.setAttribute('aria-pressed','false');}};for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,release);b.addEventListener('contextmenu',e=>e.preventDefault());}

