function setIconCue(el,icon,label,svg=false){
  if(el.dataset.cue!==icon||!el.firstElementChild){el.innerHTML=svg?`<use href="#cue-${icon}"/>`:`<svg class="cue-icon" aria-hidden="true"><use href="#cue-${icon}"/></svg>`;el.dataset.cue=icon;}
  if(el.dataset.cueLabel!==label){el.setAttribute('aria-label',label);el.setAttribute('title',label);el.dataset.cueLabel=label;}
}
function updateBossLesson(){
  const playing=state==='playing',active=boss?.active&&boss.hp>0;
  if(playing&&mode!=='trial'&&stage===0&&active&&boss.vulnerable&&!bossLessonSeen){bossLessonSeen=true;bossLessonTime=6.5;try{localStorage.setItem('sarah-boss-cue-v1','1');}catch{}}
  const show=playing&&stage===0&&active&&bossLessonTime>0;
  $('boss-lesson').style.display=show?'flex':'none';
  if(show){const coarse=window.matchMedia?.('(pointer: coarse)').matches;$('boss-lesson').classList.toggle('touch-lesson',!!coarse);}
}
function drawLaunchPads(t){releaseLaunchPads(t);}
function drawSurfaceRipples(){ctx.save();for(const r of surfaceRipples){const p=1-r.life;ctx.globalAlpha=r.life*.8;ctx.strokeStyle='#c3fff4';ctx.lineWidth=2.5*r.life;for(let i=0;i<2;i++){ctx.beginPath();ctx.ellipse(r.x-camera,r.y,25+p*(r.landing?140:110)+i*15,4+p*12+i*3,0,0,Math.PI*2);ctx.stroke();}}ctx.restore();}

