 if(fade<.05)return;
 const bands=variant==='boss'?3:variant==='combo'?2:1,colors=variant==='boss'?['#fff1ad','#edb2ff','#a1fff1']:variant==='combo'?['#ffbadc','#fff0b4']:['#b6fff3'];
